const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const cors = require('cors');

const db = require('./db');
const ordiniRouter = require('./routes/ordini');
const menuRouter = require('./routes/menu');
const scorteRouter = require('./routes/scorte');
const stampantiRouter = require('./routes/stampanti');
const smistatoreRouter = require('./routes/smistatore');
const stampeRouter = require('./routes/stampe');
const predittoreRouter = require('./routes/predittore');
const smistatore = require('./services/smistatore');
const dispatcher = require('./services/printer-dispatcher');
const emulatore = require('./services/escpos-emulator');

const app = express();
const server = http.createServer(app);

// Socket.io: permette ai client di ricevere aggiornamenti in tempo reale
const io = new Server(server, {
    cors: {
        origin: '*',
        methods: ['GET', 'POST']
    }
});

// Rendiamo io disponibile nelle route tramite app.locals
app.locals.io = io;

app.use(cors());
app.use(express.json());

// Route API
app.use('/api/ordini', ordiniRouter);
app.use('/api/menu', menuRouter);
app.use('/api/scorte', scorteRouter);
app.use('/api/stampanti', stampantiRouter);
app.use('/api/smistatore', smistatoreRouter);
app.use('/api/stampe', stampeRouter);
app.use('/api/predittore', predittoreRouter);

// Inietta socket.io nei servizi che emettono eventi WebSocket
dispatcher.setIo(io);
emulatore.setIo(io);

// Healthcheck
app.get('/api/health', (req, res) => {
    res.json({ stato: 'ok', timestamp: new Date().toISOString() });
});

// Gestione connessioni WebSocket
io.on('connection', (socket) => {
    console.log(`Client connesso: ${socket.id}`);

    socket.on('disconnect', () => {
        console.log(`Client disconnesso: ${socket.id}`);
    });
});

const PORT = process.env.PORT || 3001;

// Aspettiamo che il database sia pronto prima di avviare il server
async function avviaServer() {
    let tentativi = 0;
    while (tentativi < 10) {
        try {
            await db.query('SELECT 1');
            console.log('Database connesso correttamente');

            // Migrazione: crea tabella voce_composizione se non esiste
            await db.query(`
                CREATE TABLE IF NOT EXISTS voce_composizione (
                    voce_aggregata_id INT NOT NULL,
                    voce_componente_id INT NOT NULL,
                    PRIMARY KEY (voce_aggregata_id, voce_componente_id),
                    FOREIGN KEY (voce_aggregata_id) REFERENCES voce(id) ON DELETE CASCADE,
                    FOREIGN KEY (voce_componente_id) REFERENCES voce(id) ON DELETE CASCADE
                )
            `);

            // Migrazione: crea tabella scorta_storico se non esiste
            await db.query(`
                CREATE TABLE IF NOT EXISTS scorta_storico (
                    id INT AUTO_INCREMENT PRIMARY KEY,
                    voce_id INT NOT NULL,
                    quantita INT NOT NULL,
                    data_rifornimento DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    note VARCHAR(255),
                    FOREIGN KEY (voce_id) REFERENCES voce(id) ON DELETE CASCADE
                )
            `);

            // Migrazione: fix duplicati scorta e aggiunta vincolo UNIQUE su voce_id
            try {
                // Verifica se il vincolo UNIQUE esiste già
                const [indexes] = await db.query(
                    `SHOW INDEX FROM scorta WHERE Column_name = 'voce_id' AND Non_unique = 0`
                );
                if (indexes.length === 0) {
                    // Rimuovi righe duplicate (tieni quella con id più alto per ogni voce)
                    await db.query(`
                        DELETE s1 FROM scorta s1
                        INNER JOIN scorta s2 ON s1.voce_id = s2.voce_id AND s1.id < s2.id
                    `);
                    // Aggiungi vincolo UNIQUE
                    await db.query('ALTER TABLE scorta ADD UNIQUE KEY uk_voce_id (voce_id)');
                    console.log('Migrazione scorta: vincolo UNIQUE aggiunto su voce_id');
                }
            } catch (errMigrazione) {
                console.log('Migrazione scorta UNIQUE:', errMigrazione.message);
            }

            // Migrazione: rimappa TUTTI i colori al più vicino nella palette soft
            try {
                const PALETTE = ['#4A90D9', '#5BA85E', '#D45454', '#E8B84B', '#9370BE', '#4A4E5A'];

                function hexToRgb(hex) {
                    const h = hex.replace('#', '');
                    return [parseInt(h.substr(0,2),16), parseInt(h.substr(2,2),16), parseInt(h.substr(4,2),16)];
                }
                function distanza(a, b) {
                    return Math.sqrt((a[0]-b[0])**2 + (a[1]-b[1])**2 + (a[2]-b[2])**2);
                }
                function coloreVicino(hex) {
                    try {
                        const rgb = hexToRgb(hex);
                        return PALETTE.reduce((best, p) => distanza(rgb, hexToRgb(p)) < distanza(rgb, hexToRgb(best)) ? p : best);
                    } catch { return '#4A90D9'; }
                }

                const [voci] = await db.query('SELECT id, colore_tasto FROM voce');
                for (const voce of voci) {
                    const nuovo = coloreVicino(voce.colore_tasto || '#4A90D9');
                    if (nuovo !== voce.colore_tasto) {
                        await db.query('UPDATE voce SET colore_tasto = ? WHERE id = ?', [nuovo, voce.id]);
                    }
                }
                console.log('Migrazione palette: colori normalizzati');
            } catch (errMigrazione) {
                console.log('Migrazione palette:', errMigrazione.message);
            }

            // Migrazione: aggiunge colonna tempo_preparazione su voce (per lo smistatore)
            try {
                const [cols] = await db.query(
                    `SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                     WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'voce' AND COLUMN_NAME = 'tempo_preparazione'`
                );
                if (cols.length === 0) {
                    await db.query(`ALTER TABLE voce ADD COLUMN tempo_preparazione INT NOT NULL DEFAULT 60`);
                    console.log('Migrazione voce: colonna tempo_preparazione aggiunta');
                }
            } catch (errMigrazione) {
                console.log('Migrazione tempo_preparazione:', errMigrazione.message);
            }

            // Migrazione: colonne Predittore Scorte su voce (tempo_riapprovvigionamento, priorita_voce)
            try {
                const colonneVoce = [
                    { nome: 'tempo_riapprovvigionamento', ddl: 'ADD COLUMN tempo_riapprovvigionamento INT NOT NULL DEFAULT 600' },
                    { nome: 'priorita_voce', ddl: "ADD COLUMN priorita_voce ENUM('bassa','media','alta') NOT NULL DEFAULT 'media'" },
                ];
                const [colsVoce] = await db.query(
                    `SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                     WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'voce'`
                );
                const presentiVoce = new Set(colsVoce.map(c => c.COLUMN_NAME));
                for (const col of colonneVoce) {
                    if (!presentiVoce.has(col.nome)) {
                        await db.query(`ALTER TABLE voce ${col.ddl}`);
                        console.log(`Migrazione voce: colonna ${col.nome} aggiunta`);
                    }
                }
            } catch (errMigrazione) {
                console.log('Migrazione voce predittore:', errMigrazione.message);
            }

            // Migrazione: tabella configurazione (chiave/valore) per parametri runtime
            try {
                await db.query(`
                    CREATE TABLE IF NOT EXISTS configurazione (
                        chiave VARCHAR(50) PRIMARY KEY,
                        valore VARCHAR(255) NOT NULL
                    )
                `);
                await db.query(`
                    INSERT IGNORE INTO configurazione (chiave, valore) VALUES
                    ('evento_fine_oggi', '23:30'),
                    ('soglia_warn_urgenza', '300'),
                    ('giorni_storico', '30')
                `);
            } catch (errMigrazione) {
                console.log('Migrazione configurazione:', errMigrazione.message);
            }

            // Migrazione: nuove colonne su stampante (modello, nome, primaria, attiva)
            try {
                const colonneRichieste = [
                    { nome: 'nome', ddl: 'ADD COLUMN nome VARCHAR(50)' },
                    { nome: 'modello', ddl: "ADD COLUMN modello VARCHAR(20) NOT NULL DEFAULT 'EPSON'" },
                    { nome: 'primaria', ddl: 'ADD COLUMN primaria TINYINT(1) NOT NULL DEFAULT 1' },
                    { nome: 'attiva', ddl: 'ADD COLUMN attiva TINYINT(1) NOT NULL DEFAULT 1' },
                ];
                const [cols] = await db.query(
                    `SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                     WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'stampante'`
                );
                const presenti = new Set(cols.map(c => c.COLUMN_NAME));
                for (const col of colonneRichieste) {
                    if (!presenti.has(col.nome)) {
                        await db.query(`ALTER TABLE stampante ${col.ddl}`);
                        console.log(`Migrazione stampante: colonna ${col.nome} aggiunta`);
                    }
                }
            } catch (errMigrazione) {
                console.log('Migrazione stampante:', errMigrazione.message);
            }

            // Migrazione: riporta le stampanti su 127.0.0.1 (emulatore locale) se sono
            // ancora puntate ai placeholder 192.168.1.x del dataset di esempio originale.
            try {
                const mapping = [
                    { reparto: 'cucina', porta: 9100, nome: 'Stampante Cucina' },
                    { reparto: 'bar', porta: 9101, nome: 'Stampante Bar' },
                    { reparto: 'griglia', porta: 9102, nome: 'Stampante Griglia' },
                ];
                for (const m of mapping) {
                    await db.query(
                        `UPDATE stampante
                         SET indirizzo_ip = '127.0.0.1', porta = ?, nome = COALESCE(nome, ?)
                         WHERE reparto = ? AND indirizzo_ip LIKE '192.168.%'`,
                        [m.porta, m.nome, m.reparto]
                    );
                }
            } catch (errMigrazione) {
                console.log('Migrazione IP stampanti:', errMigrazione.message);
            }

            // Migrazione: aggiungi seconda cucina (cucina_2) se mancante.
            // Serve per dimostrare il bilanciamento del carico nello smistatore.
            try {
                const [c2] = await db.query(`SELECT id FROM stampante WHERE reparto = 'cucina_2'`);
                if (c2.length === 0) {
                    await db.query(
                        `INSERT INTO stampante (reparto, nome, indirizzo_ip, porta, modello)
                         VALUES ('cucina_2', 'Cucina B', '127.0.0.1', 9103, 'EPSON')`
                    );
                    // Mentre ci siamo, rinominiamo la cucina originale a "Cucina A"
                    await db.query(
                        `UPDATE stampante SET nome = 'Cucina A'
                         WHERE reparto = 'cucina' AND (nome IS NULL OR nome = 'Stampante Cucina')`
                    );
                    console.log('Migrazione stampante: cucina_2 aggiunta (Cucina B su porta 9103)');
                }
            } catch (errMigrazione) {
                console.log('Migrazione cucina_2:', errMigrazione.message);
            }

            // Migrazione: rimuove ordine_schermo (ordinamento alfabetico in cassa)
            try {
                const [colsOrdine] = await db.query(
                    `SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                     WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'voce' AND COLUMN_NAME = 'ordine_schermo'`
                );
                if (colsOrdine.length > 0) {
                    await db.query('ALTER TABLE voce DROP COLUMN ordine_schermo');
                    console.log('Migrazione voce: colonna ordine_schermo rimossa');
                }
            } catch (errMigrazione) {
                console.log('Migrazione ordine_schermo:', errMigrazione.message);
            }

            // Migrazione: copia scontrino cliente su voce
            try {
                const [colsCopia] = await db.query(
                    `SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                     WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'voce' AND COLUMN_NAME = 'copia_scontrino_cliente'`
                );
                if (colsCopia.length === 0) {
                    await db.query('ALTER TABLE voce ADD COLUMN copia_scontrino_cliente TINYINT(1) NOT NULL DEFAULT 0');
                    console.log('Migrazione voce: colonna copia_scontrino_cliente aggiunta');
                }
            } catch (errMigrazione) {
                console.log('Migrazione copia_scontrino_cliente:', errMigrazione.message);
            }

            // Migrazione: stampante cassa (copia cliente)
            try {
                const [cassa] = await db.query(`SELECT id FROM stampante WHERE reparto = 'cassa'`);
                if (cassa.length === 0) {
                    await db.query(
                        `INSERT INTO stampante (reparto, nome, indirizzo_ip, porta, modello, primaria, attiva)
                         VALUES ('cassa', 'Stampante Cassa', '127.0.0.1', 9104, 'EPSON', 1, 1)`
                    );
                    console.log('Migrazione stampante: cassa aggiunta (porta 9104)');
                } else {
                    await db.query(
                        `UPDATE stampante
                         SET nome = COALESCE(NULLIF(nome, ''), 'Stampante Cassa'),
                             indirizzo_ip = '127.0.0.1',
                             porta = 9104,
                             primaria = 1,
                             attiva = 1
                         WHERE reparto = 'cassa'`
                    );
                }
            } catch (errMigrazione) {
                console.log('Migrazione stampante cassa:', errMigrazione.message);
            }

            // Migrazione: crea tabella stampa_eseguita (audit log delle stampe)
            try {
                await db.query(`
                    CREATE TABLE IF NOT EXISTS stampa_eseguita (
                        id INT AUTO_INCREMENT PRIMARY KEY,
                        ordine_id INT NOT NULL,
                        stampante_id INT,
                        reparto VARCHAR(50) NOT NULL,
                        payload JSON,
                        esito ENUM('ok', 'errore', 'offline_rerouted', 'no_stampante') NOT NULL,
                        errore TEXT,
                        durata_ms INT,
                        timestamp DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (ordine_id) REFERENCES ordine(id) ON DELETE CASCADE,
                        FOREIGN KEY (stampante_id) REFERENCES stampante(id) ON DELETE SET NULL,
                        INDEX idx_ordine (ordine_id),
                        INDEX idx_timestamp (timestamp)
                    )
                `);
            } catch (errMigrazione) {
                console.log('Migrazione stampa_eseguita:', errMigrazione.message);
            }

            // Inizializzazione smistatore: carica stato stampanti dal DB
            try {
                const [stampanti] = await db.query('SELECT reparto, stato FROM stampante');
                for (const s of stampanti) {
                    smistatore.setStatoStampante(s.reparto, s.stato === 'offline' ? 'offline' : 'online');
                }
                console.log(`Smistatore: caricate ${stampanti.length} stampanti`);

                // Fallback default per il bilanciamento del carico tra le due cucine.
                // Le voci con settore_stampa='cucina' verranno smistate da selectMinCarico
                // tra cucina e cucina_2 in base al carico istantaneo.
                const repartiSet = new Set(stampanti.map(s => s.reparto));
                if (repartiSet.has('cucina') && repartiSet.has('cucina_2')) {
                    smistatore.setFallback('cucina', ['cucina_2']);
                    smistatore.setFallback('cucina_2', ['cucina']);
                    console.log('Smistatore: fallback bidirezionale cucina <-> cucina_2 configurato');
                }
            } catch (errInit) {
                console.log('Init smistatore:', errInit.message);
            }

            // Avvio emulatori TCP ESC/POS (modalità demo: stampanti su 127.0.0.1)
            // Disabilitabile con EMULATORE_ATTIVO=0 in produzione con hardware reale.
            if (process.env.EMULATORE_ATTIVO !== '0') {
                try {
                    const n = await emulatore.avviaEmulatori(db);
                    const [lista] = await db.query(
                        `SELECT reparto, nome, porta FROM stampante ORDER BY porta`
                    );
                    console.log(`Emulatore ESC/POS: ${n} listener avviati — stampanti: ${lista.map(s => `${s.reparto}(:${s.porta})`).join(', ')}`);
                } catch (errEmu) {
                    console.log('Avvio emulatori:', errEmu.message);
                }
            } else {
                console.log('Emulatore ESC/POS: disabilitato (EMULATORE_ATTIVO=0)');
            }

            // Migrazione: inizializza scorte a 10 per tutti i prodotti
            try {
                // Aggiorna scorte esistenti a 10
                await db.query(`UPDATE scorta SET quantita = 10`);

                // Crea scorte mancanti per i prodotti che non le hanno
                await db.query(`
                    INSERT INTO scorta (voce_id, quantita, soglia_giallo, soglia_rosso, attiva)
                    SELECT id, 10, 10, 3, 1 FROM voce v
                    WHERE NOT EXISTS (SELECT 1 FROM scorta s WHERE s.voce_id = v.id)
                `);
                console.log('Migrazione scorte: tutte impostate a quantità 10');
            } catch (errMigrazione) {
                console.log('Migrazione scorte default:', errMigrazione.message);
            }

            console.log('Migrazione completata');

            break;
        } catch (err) {
            tentativi++;
            console.log(`Attesa database... tentativo ${tentativi}/10`);
            await new Promise(r => setTimeout(r, 3000));
        }
    }

    server.listen(PORT, () => {
        console.log(`Backend avviato su porta ${PORT}`);
    });
}

avviaServer();

const express = require('express');
const router = express.Router();
const db = require('../db');

// GET /api/menu - tutte le voci visibili (per la cassa)
router.get('/', async (req, res) => {
    try {
        const [voci] = await db.query(
            `SELECT v.*, s.quantita as scorta_quantita, s.soglia_giallo, s.soglia_rosso, s.attiva as scorta_attiva
             FROM voce v
             LEFT JOIN scorta s ON s.voce_id = v.id
             WHERE v.visibile = 1
             ORDER BY v.settore_visualizzazione, v.nome`
        );
        res.json(voci);
    } catch (err) {
        res.status(500).json({ errore: err.message });
    }
});

// GET /api/menu/settori - lista distinta dei settori con conteggio voci
router.get('/settori', async (req, res) => {
    try {
        const [settori] = await db.query(
            `SELECT 
                settore_visualizzazione,
                COUNT(*) as num_pietanze,
                (SELECT colore_tasto FROM voce v2 
                 WHERE v2.settore_visualizzazione = voce.settore_visualizzazione 
                 GROUP BY colore_tasto ORDER BY COUNT(*) DESC LIMIT 1
                ) as colore
             FROM voce
             WHERE settore_visualizzazione IS NOT NULL AND settore_visualizzazione != ''
             GROUP BY settore_visualizzazione
             ORDER BY settore_visualizzazione`
        );
        res.json(settori);
    } catch (err) {
        res.status(500).json({ errore: err.message });
    }
});

// GET /api/menu/tutti-allergeni - mappa voce_id -> [allergeni] (per precarico frontend)
router.get('/tutti-allergeni', async (req, res) => {
    try {
        const [righe] = await db.query(
            `SELECT va.voce_id, a.id, a.nome, a.descr
             FROM voce_allergene va
             JOIN allergene a ON a.id = va.allergene_id
             ORDER BY va.voce_id, a.nome`
        );
        const mappa = {};
        righe.forEach(r => {
            if (!mappa[r.voce_id]) mappa[r.voce_id] = [];
            mappa[r.voce_id].push({ id: r.id, nome: r.nome, descr: r.descr });
        });
        res.json(mappa);
    } catch (err) {
        res.status(500).json({ errore: err.message });
    }
});

// GET /api/menu/opzioni - valori distinti per i campi dropdown
router.get('/opzioni', async (req, res) => {
    try {
        const [categorie] = await db.query(
            `SELECT DISTINCT categoria FROM voce WHERE categoria IS NOT NULL AND categoria != '' ORDER BY categoria`
        );
        const [settoriStampa] = await db.query(
            `SELECT DISTINCT settore_stampa FROM voce WHERE settore_stampa IS NOT NULL AND settore_stampa != '' ORDER BY settore_stampa`
        );
        const [settoriVis] = await db.query(
            `SELECT DISTINCT settore_visualizzazione FROM voce WHERE settore_visualizzazione IS NOT NULL AND settore_visualizzazione != '' ORDER BY settore_visualizzazione`
        );
        res.json({
            categorie: categorie.map(r => r.categoria),
            settori_stampa: settoriStampa.map(r => r.settore_stampa),
            settori_visualizzazione: settoriVis.map(r => r.settore_visualizzazione)
        });
    } catch (err) {
        res.status(500).json({ errore: err.message });
    }
});

// GET /api/menu/tutte - tutte le voci incluse le nascoste (per admin), con flag aggregata
router.get('/tutte', async (req, res) => {
    try {
        const [voci] = await db.query(
            `SELECT v.*, 
                s.quantita as scorta_quantita, s.soglia_giallo, s.soglia_rosso, s.attiva as scorta_attiva,
                (SELECT COUNT(*) FROM voce_composizione vc WHERE vc.voce_aggregata_id = v.id) as num_componenti
             FROM voce v
             LEFT JOIN scorta s ON s.voce_id = v.id
             ORDER BY v.settore_visualizzazione, v.nome`
        );
        res.json(voci);
    } catch (err) {
        res.status(500).json({ errore: err.message });
    }
});

// GET /api/menu/:id/allergeni
router.get('/:id/allergeni', async (req, res) => {
    try {
        const [allergeni] = await db.query(
            `SELECT a.* FROM allergene a
             JOIN voce_allergene va ON va.allergene_id = a.id
             WHERE va.voce_id = ?`,
            [req.params.id]
        );
        res.json(allergeni);
    } catch (err) {
        res.status(500).json({ errore: err.message });
    }
});

// GET /api/menu/:id/composizione - componenti di una pietanza aggregata
router.get('/:id/composizione', async (req, res) => {
    try {
        const [componenti] = await db.query(
            `SELECT v.id, v.codice, v.nome, v.prezzo, v.categoria, v.settore_visualizzazione
             FROM voce v
             JOIN voce_composizione vc ON vc.voce_componente_id = v.id
             WHERE vc.voce_aggregata_id = ?
             ORDER BY v.nome`,
            [req.params.id]
        );
        res.json(componenti);
    } catch (err) {
        res.status(500).json({ errore: err.message });
    }
});

// Funzione helper per auto-generare il codice
async function generaCodice(categoria) {
    const prefisso = (categoria && categoria.trim().length > 0)
        ? categoria.trim()[0].toUpperCase()
        : 'X';

    const [maxCodice] = await db.query(
        `SELECT codice FROM voce WHERE codice LIKE ? ORDER BY codice DESC LIMIT 1`,
        [`${prefisso}%`]
    );

    let numero = 1;
    if (maxCodice.length > 0) {
        const match = maxCodice[0].codice.match(/\d+$/);
        if (match) numero = parseInt(match[0]) + 1;
    }

    return `${prefisso}${String(numero).padStart(3, '0')}`;
}

// POST /api/menu - aggiunge voce singola (admin) — codice auto-generato
router.post('/', async (req, res) => {
    const { nome, prezzo, categoria, settore_visualizzazione, settore_stampa, colore_tasto, copia_scontrino_cliente, asportabile, modalita_stampa } = req.body;

    if (!nome || !nome.trim()) {
        return res.status(400).json({ errore: 'Il nome è obbligatorio' });
    }

    try {
        const codice = await generaCodice(categoria);

        const [risultato] = await db.query(
            `INSERT INTO voce
             (codice, nome, prezzo, categoria, settore_visualizzazione, settore_stampa, colore_tasto, copia_scontrino_cliente, asportabile, modalita_stampa)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [codice, nome.trim(), prezzo || 0, categoria || null, settore_visualizzazione || null, settore_stampa || null, colore_tasto || '#4A90D9', copia_scontrino_cliente ? 1 : 0, asportabile !== false ? 1 : 0, modalita_stampa || 'singola_multipla']
        );

        const voceId = risultato.insertId;

        // Crea scorta di default con 10 quantità
        await db.query(
            `INSERT INTO scorta (voce_id, quantita, soglia_giallo, soglia_rosso, attiva)
             VALUES (?, ?, ?, ?, ?)`,
            [voceId, 10, 10, 3, 1]
        );

        res.status(201).json({ id: voceId, codice });
    } catch (err) {
        if (err.code === 'ER_DUP_ENTRY') {
            return res.status(409).json({ errore: 'Codice generato già in uso, riprovare' });
        }
        res.status(500).json({ errore: err.message });
    }
});

