    // Esposti per test
    _parsaFlusso: parsaFlusso,
}

// Formatter ESC/POS: converte una Comanda (oggetto JSON generato dallo smistatore)
// in un Buffer di byte conforme allo standard ESC/POS, pronto per essere inviato
// via TCP raw socket a una stampante termica (o all'emulatore di sviluppo).

const { ThermalPrinter, PrinterTypes } = require('node-thermal-printer')

// Mappa modello → tipo libreria
const MODELLI = {
    EPSON: PrinterTypes.EPSON,
    STAR: PrinterTypes.STAR,
    CUSTOM: PrinterTypes.CUSTOM,
    DARUMA: PrinterTypes.DARUMA,
}

function risolviTipo(modello) {
    return MODELLI[(modello || 'EPSON').toUpperCase()] || PrinterTypes.EPSON
}

function intestazione(printer, comanda) {
    if (comanda.asporto) {
        printer.alignCenter()
        printer.setTextDoubleHeight()
        printer.setTextDoubleWidth()
        printer.bold(true)
        printer.println('ASPORTO')
        printer.bold(false)
        printer.setTextNormal()
    }
    printer.alignCenter()
    printer.bold(true)
    printer.println(`REPARTO ${String(comanda.reparto || '').toUpperCase()}`)
    printer.bold(false)
    printer.drawLine()
}

function meta(printer, comanda) {
    const data = new Date(comanda.timestamp || Date.now())
    const ora = data.toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    printer.alignLeft()
    printer.println(`Ordine #${comanda.ordine_id}    ${ora}`)
    if (typeof comanda.tavolo === 'number') {
        printer.println(`Tavolo: ${comanda.tavolo}`)
    }
    printer.drawLine()
}

function corpo(printer, comanda) {
    printer.alignLeft()
    // Righe ordinate per P decrescente (lo smistatore già le passa così)
    for (const riga of comanda.righe || []) {
        printer.bold(true)
        printer.println(`${riga.quantita}x  ${riga.nome}`)
        printer.bold(false)
        // Note per porzione: deduplica per non stampare la stessa nota N volte
        const noteUniche = new Map()
        for (const n of (riga.note || [])) {
            const k = `${n.numero_porzione || 0}|${n.testo}`
            if (!noteUniche.has(k)) noteUniche.set(k, n)
        }
        for (const n of noteUniche.values()) {
            const prefisso = n.numero_porzione ? `  [${n.numero_porzione}] > ` : '  > '
            printer.println(`${prefisso}${n.testo}`)
        }
    }
}

function piede(printer) {
    printer.drawLine()
    printer.alignCenter()
    printer.println('** FINE COMANDA **')
    printer.cut()
}

function intestazioneCopiaCliente(printer, dati) {
    if (dati.asporto) {
        printer.alignCenter()
        printer.setTextDoubleHeight()
        printer.setTextDoubleWidth()
        printer.bold(true)
        printer.println('ASPORTO')
        printer.bold(false)
        printer.setTextNormal()
    }
    printer.alignCenter()
    printer.bold(true)
    printer.println('COPIA CLIENTE')
    printer.bold(false)
    printer.drawLine()
}

function corpoCopiaCliente(printer, dati) {
    printer.alignLeft()
    for (const riga of dati.righe || []) {
        const prezzo = parseFloat(riga.prezzo || 0)
        const subtotale = parseFloat((riga.quantita * prezzo).toFixed(2))
        printer.bold(true)
        printer.println(`${riga.quantita}x  ${riga.nome}`)
        printer.bold(false)
        printer.println(`    ${prezzo.toFixed(2)} EUR  =  ${subtotale.toFixed(2)} EUR`)
        const noteUniche = new Map()
        for (const n of (riga.note || [])) {
            const k = `${n.numero_porzione || 0}|${n.testo}`
            if (!noteUniche.has(k)) noteUniche.set(k, n)
        }
        for (const n of noteUniche.values()) {
            const prefisso = n.numero_porzione ? `  [${n.numero_porzione}] > ` : '  > '
            printer.println(`${prefisso}${n.testo}`)
        }
    }
    printer.drawLine()
    printer.bold(true)
    printer.println(`TOTALE:     ${parseFloat(dati.totale || 0).toFixed(2)} EUR`)
    printer.println(`PAGATO:     ${parseFloat(dati.importo_pagato || 0).toFixed(2)} EUR`)
    if (dati.resto != null && dati.resto > 0) {
        printer.println(`RESTO:      ${dati.resto.toFixed(2)} EUR`)
    }
    printer.bold(false)
}

async function formattaCopiaCliente(dati, opzioni = {}) {
    const printer = new ThermalPrinter({
        type: risolviTipo(opzioni.modello),
        interface: 'tcp://127.0.0.1:1',
        characterSet: 'PC858_EURO',
        removeSpecialCharacters: false,
        lineCharacter: '-',
        width: opzioni.larghezza_caratteri || 32,
    })

    intestazioneCopiaCliente(printer, dati)
    meta(printer, dati)
    corpoCopiaCliente(printer, dati)
    printer.drawLine()
    printer.alignCenter()
    printer.println('** FINE SCONTRINO **')
    printer.cut()

    return printer.getBuffer()
}

// Costruisce un buffer ESC/POS per la comanda data.
// L'oggetto opzioni può specificare: modello, larghezza_caratteri (default 32).
async function formattaComanda(comanda, opzioni = {}) {
    // interface fittizia: la libreria la richiede per istanziare, ma noi usiamo
    // solo getBuffer() — l'I/O reale lo gestisce il dispatcher via net.Socket().
    const printer = new ThermalPrinter({
        type: risolviTipo(opzioni.modello),
        interface: 'tcp://127.0.0.1:1',
        characterSet: 'PC858_EURO',
        removeSpecialCharacters: false,
        lineCharacter: '-',
        width: opzioni.larghezza_caratteri || 32,
    })

    intestazione(printer, comanda)
    meta(printer, comanda)
    corpo(printer, comanda)
    piede(printer)

    return printer.getBuffer()
}

// Espande una comanda in N buffer secondo la modalità di stampa.
// - singola_multipla (default): 1 buffer con tutte le righe
// - singola_singola: N buffer (uno per porzione di ogni riga)
// - doppia_copia: 2 buffer identici
async function pagineDaInviare(comanda, modalita_stampa = 'singola_multipla', opzioni = {}) {
    const modalita = String(modalita_stampa || 'singola_multipla').toLowerCase()

    if (modalita === 'doppia_copia') {
        const buf = await formattaComanda(comanda, opzioni)
        return [buf, buf]
    }

    if (modalita === 'singola_singola') {
        const pagine = []
        for (const riga of (comanda.righe || [])) {
            for (let i = 1; i <= riga.quantita; i++) {
                const notePorzione = (riga.note || []).filter(n => !n.numero_porzione || n.numero_porzione === i)
                const comandaPorzione = {
                    ...comanda,
                    righe: [{ ...riga, quantita: 1, note: notePorzione.map(n => ({ ...n, numero_porzione: undefined })) }],
                }
                pagine.push(await formattaComanda(comandaPorzione, opzioni))
            }
        }
        return pagine.length > 0 ? pagine : [await formattaComanda(comanda, opzioni)]
    }

    // singola_multipla
    return [await formattaComanda(comanda, opzioni)]
}

// Pagina di test (richiesta da admin per verificare connessione + carta)
async function pagineDiTest(stampante) {
    const comandaTest = {
        ordine_id: 0,
        reparto: stampante.reparto,
        asporto: false,
        timestamp: Date.now(),
        righe: [
            { quantita: 1, nome: 'PAGINA DI TEST', note: [] },
            { quantita: 1, nome: `${stampante.nome || stampante.reparto}`, note: [{ testo: `${stampante.indirizzo_ip}:${stampante.porta}` }] },
            { quantita: 1, nome: 'Stampa OK se leggi questo', note: [] },
        ],
    }
    return pagineDaInviare(comandaTest, 'singola_multipla', { modello: stampante.modello })
}

module.exports = {
    formattaComanda,
    formattaCopiaCliente,
    pagineDaInviare,
    pagineDiTest,
}

// Predittore Dinamico di Riordino Scorte (UC5b)
//
// Per ogni voce attiva del menu calcola:
//  - consumo atteso (media pesata multi-finestra)
//  - tempo stimato di esaurimento
//  - indice di urgenza U
//  - classificazione: stabile | attenzione | urgente | esaurito
//
// Formule (vedi PIANO_PREDITTORE.md):
//   consumo_atteso = α·c_15min + β·c_1h + γ·media_storica
//   tempo_esaur    = quantita / consumo_atteso
//   U              = max(0, t_riapp - t_esaur) · priorita_voce
//                    × moltiplicatore_contesto se t_esaur < t_residuo_evento
//
// Unità interne: tassi in unità/minuto, tempi in secondi.

const db = require('../db')

// ───── Costanti dell'algoritmo ─────────────────────────────────────────────
const PESI_NORMALE = { alpha: 0.5, beta: 0.3, gamma: 0.2 }
const PESI_PICCO = { alpha: 0.8, beta: 0.15, gamma: 0.05 }
const SOGLIA_PICCO_MULT = 2.0           // c_15min > 2 × media_storica → picco
const MIN_OCCORRENZE_STORICHE = 3       // sotto questo → modalità prudente
const MOLTIPLICATORE_CONTESTO = 1.2     // se esaur < residuo evento
const MOLTIPLICATORE_SUGGERIMENTO = 1.3 // ceil(consumo · t_riapp · 1.3)
const PRIORITA_VALORE = { bassa: 0.5, media: 1.0, alta: 1.5 }

// ───── Lettura configurazione runtime dal DB ───────────────────────────────
async function leggiConfigurazione() {
    const [righe] = await db.query('SELECT chiave, valore FROM configurazione')
    const mappa = {}
    for (const r of righe) mappa[r.chiave] = r.valore
    return {
        evento_fine_oggi: mappa.evento_fine_oggi || '23:30',
        soglia_warn_urgenza: parseFloat(mappa.soglia_warn_urgenza || '300'),
        giorni_storico: parseInt(mappa.giorni_storico || '30'),
    }
}

// Calcola secondi residui all'evento (config "HH:MM" oggi).
// Se siamo già oltre l'orario, ritorna 0.
function tempoResiduoEventoSec(orarioHHMM, adesso = new Date()) {
    const [hh, mm] = String(orarioHHMM).split(':').map(s => parseInt(s, 10))
    if (isNaN(hh) || isNaN(mm)) return 0
    const fine = new Date(adesso)
    fine.setHours(hh, mm, 0, 0)
    const diffMs = fine.getTime() - adesso.getTime()
    return Math.max(0, Math.floor(diffMs / 1000))
}

// ───── Aggregazione consumi: SOMMA quantità vendute in una finestra ───────
// Ritorna: Map<voce_id, somma>
async function aggregaConsumiFinestra(minutiIndietro) {
    const [righe] = await db.query(
        `SELECT r.voce_id, COALESCE(SUM(r.quantita), 0) AS totale
         FROM ordine_riga r
         JOIN ordine o ON o.id = r.ordine_id
         WHERE o.stato = 'confermato'
           AND o.timestamp >= (NOW() - INTERVAL ? MINUTE)
         GROUP BY r.voce_id`,
        [minutiIndietro]
    )
    const mappa = new Map()
    for (const r of righe) mappa.set(r.voce_id, Number(r.totale))
    return mappa
}

// Media storica per la fascia oraria CORRENTE (HOUR(NOW())):
// per ogni voce, media delle SOMME quantità raggruppate per data, considerando
// solo gli ordini confermati nei `giorniLookback` giorni passati nella stessa
// ora del giorno.
// Ritorna: Map<voce_id, { media_unita_ora, occorrenze }>
async function mediaStoricaFascia(giorniLookback, adesso = new Date()) {
    const oraCorrente = adesso.getHours()
    const [righe] = await db.query(
        `SELECT voce_id, AVG(somma_giornaliera) AS media_unita_ora, COUNT(*) AS occorrenze
         FROM (
             SELECT r.voce_id, DATE(o.timestamp) AS giorno,
                    SUM(r.quantita) AS somma_giornaliera
             FROM ordine_riga r
             JOIN ordine o ON o.id = r.ordine_id
             WHERE o.stato = 'confermato'
               AND HOUR(o.timestamp) = ?
               AND o.timestamp >= (NOW() - INTERVAL ? DAY)
               AND o.timestamp <  (NOW() - INTERVAL 1 HOUR)
             GROUP BY r.voce_id, DATE(o.timestamp)
         ) AS t
         GROUP BY voce_id`,
        [oraCorrente, giorniLookback]
    )
    const mappa = new Map()
    for (const r of righe) {
        mappa.set(r.voce_id, {
            media_unita_ora: Number(r.media_unita_ora) || 0,
            occorrenze: Number(r.occorrenze) || 0,
        })
    }
    return mappa
}

// ───── Calcolo pesi (modalità) ─────────────────────────────────────────────
function calcolaPesi({ consumo15Min, mediaStoricaUnitaOra, occorrenzeStoriche }) {
    // Modalità prudente: pochi dati storici → ignoriamo γ e ridistribuiamo
    if (occorrenzeStoriche < MIN_OCCORRENZE_STORICHE) {
        return { alpha: PESI_NORMALE.alpha + PESI_NORMALE.gamma * (5 / 7),
                 beta:  PESI_NORMALE.beta  + PESI_NORMALE.gamma * (2 / 7),
                 gamma: 0,
                 modalita: 'prudente' }
    }
    // Modalità picco: c_15min > 2 × media_storica (su scala unità/min comparabile)
    // c_15min è già unità in 15min → tasso = c_15min / 15
    // media_storica_unita_ora → tasso = media / 60
    const tasso15 = consumo15Min / 15
    const tassoStorico = mediaStoricaUnitaOra / 60
    if (tassoStorico > 0 && tasso15 > SOGLIA_PICCO_MULT * tassoStorico) {
        return { ...PESI_PICCO, modalita: 'picco' }
    }
    return { ...PESI_NORMALE, modalita: 'normale' }
}

// ───── Consumo atteso (tasso unità/minuto) ─────────────────────────────────
function consumoAtteso(pesi, consumo15Min, consumo1h, mediaStoricaUnitaOra) {
    // Tutti i contributi normalizzati a unità/minuto per omogeneità
    const tasso15 = consumo15Min / 15
    const tasso1h = consumo1h / 60
    const tassoStorico = mediaStoricaUnitaOra / 60
    return pesi.alpha * tasso15 + pesi.beta * tasso1h + pesi.gamma * tassoStorico
}

// ───── Tempo di esaurimento (in secondi) ───────────────────────────────────
function tempoEsaurimentoSec(quantita, consumoAttesoUnitaMin) {
    if (!consumoAttesoUnitaMin || consumoAttesoUnitaMin <= 0) return Infinity
    const minuti = quantita / consumoAttesoUnitaMin
    return minuti * 60
}

// ───── Indice di urgenza U ─────────────────────────────────────────────────
function calcolaU({ tempoRiappSec, tempoEsaurSec, priorita, tempoResiduoEventoSec: tRes }) {
    const moltPriorita = PRIORITA_VALORE[priorita] || 1.0
    const tEsaur = tempoEsaurSec === Infinity ? Number.MAX_SAFE_INTEGER : tempoEsaurSec
    let U = Math.max(0, tempoRiappSec - tEsaur) * moltPriorita
    // Moltiplicatore di contesto: l'esaurimento avverrà prima della fine evento?
    if (tEsaur < tRes && tEsaur < Number.MAX_SAFE_INTEGER) {
        U *= MOLTIPLICATORE_CONTESTO
    }
    return U
}

// ───── Classificazione ─────────────────────────────────────────────────────
function classifica({ quantita, U, statoScorta, sogliaWarn }) {
    if (quantita <= 0) return 'esaurito'
    if (U === 0 && (statoScorta === 'disponibile' || statoScorta === 'sconosciuto')) return 'stabile'
    if (U > 0 && U <= sogliaWarn) return 'attenzione'
    if (U > sogliaWarn) return 'urgente'
    return 'stabile'
}

function quantitaSuggerita(consumoAttesoUnitaMin, tempoRiappSec) {
    const tempoRiappMin = tempoRiappSec / 60
    return Math.ceil(consumoAttesoUnitaMin * tempoRiappMin * MOLTIPLICATORE_SUGGERIMENTO)
}

// ───── Aggregazione ingredienti condivisi ─────────────────────────────────
// Se più voci condividono un contatore aggregato (tabella voce_contatore),
// il consumo "effettivo" che impatta la scorta condivisa è la somma di tutte
// le voci collegate. Aggiorniamo i consumi delle voci coinvolte per riflettere
// questo, in modo che il loro indice U sia calcolato sul consumo aggregato.
async function indiciCondivisione() {
    try {
        const [righe] = await db.query(
            `SELECT contatore_id, GROUP_CONCAT(voce_id) AS voci
             FROM voce_contatore
             GROUP BY contatore_id`
        )
        const gruppi = []
        for (const r of righe) {
            const voci = String(r.voci).split(',').map(Number).filter(Boolean)
            if (voci.length > 1) gruppi.push(voci)
        }
        return gruppi
    } catch {
        return []
    }
}

function aggregaConsumiCondivisi(consumiMap, gruppiCondivisi) {
    // Per ogni gruppo, somma i consumi e riassegna ad ogni voce del gruppo
    // il totale aggregato (così l'urgenza riflette la pressione condivisa)
    const aggregato = new Map()
    for (const [voce_id, valore] of consumiMap) aggregato.set(voce_id, valore)
    for (const gruppo of gruppiCondivisi) {
        let somma = 0
        for (const v of gruppo) somma += consumiMap.get(v) || 0
        for (const v of gruppo) aggregato.set(v, somma)
    }
    return aggregato
}

// ───── Main: eseguiPredizione() ───────────────────────────────────────────
async function eseguiPredizione({ filtroVociIds = null } = {}) {
    const config = await leggiConfigurazione()
    const tRes = tempoResiduoEventoSec(config.evento_fine_oggi)

    // Carica voci attive (visibili + scorta attiva) — escludi non vendibili
    let queryVoci = `
        SELECT v.id, v.codice, v.nome, v.settore_stampa, v.tempo_riapprovvigionamento,
               v.priorita_voce, s.quantita, s.soglia_giallo, s.soglia_rosso, s.attiva
        FROM voce v
        LEFT JOIN scorta s ON s.voce_id = v.id
        WHERE v.visibile = 1`
    const params = []
    if (filtroVociIds && filtroVociIds.length) {
        queryVoci += ' AND v.id IN (?)'
        params.push(filtroVociIds)
    }
    const [voci] = await db.query(queryVoci, params)

    // Consumi finestre temporali e storico
    const [c15, c1h, storico, gruppiCondivisi] = await Promise.all([
        aggregaConsumiFinestra(15),
        aggregaConsumiFinestra(60),
        mediaStoricaFascia(config.giorni_storico),
        indiciCondivisione(),
    ])

    // Aggregazione ingredienti condivisi: applico ai consumi 15min e 1h
    const c15Agg = aggregaConsumiCondivisi(c15, gruppiCondivisi)
    const c1hAgg = aggregaConsumiCondivisi(c1h, gruppiCondivisi)

    const risultati = []
    for (const v of voci) {
        const consumo15 = c15Agg.get(v.id) || 0
        const consumo1h = c1hAgg.get(v.id) || 0
        const storicoVoce = storico.get(v.id) || { media_unita_ora: 0, occorrenze: 0 }

        const pesi = calcolaPesi({
            consumo15Min: consumo15,
            mediaStoricaUnitaOra: storicoVoce.media_unita_ora,
            occorrenzeStoriche: storicoVoce.occorrenze,
        })

        const consumoAttUnitaMin = consumoAtteso(pesi, consumo15, consumo1h, storicoVoce.media_unita_ora)
        const tempoEsaurSec = tempoEsaurimentoSec(v.quantita || 0, consumoAttUnitaMin)

        const U = calcolaU({
            tempoRiappSec: v.tempo_riapprovvigionamento,
            tempoEsaurSec,
            priorita: v.priorita_voce,
            tempoResiduoEventoSec: tRes,
        })

        // Stato visivo derivato per la classificazione
        let statoVisivo = 'sconosciuto'
        if (!v.attiva) statoVisivo = 'sconosciuto'
        else if ((v.quantita || 0) === 0) statoVisivo = 'esaurito'
        else if ((v.quantita || 0) <= (v.soglia_rosso || 0)) statoVisivo = 'critico'
        else if ((v.quantita || 0) <= (v.soglia_giallo || 0)) statoVisivo = 'attenzione'
        else statoVisivo = 'disponibile'

        const stato = classifica({
            quantita: v.quantita || 0,
            U,
            statoScorta: statoVisivo,
            sogliaWarn: config.soglia_warn_urgenza,
        })

        risultati.push({
            voce_id: v.id,
            codice: v.codice,
            nome: v.nome,
            reparto: v.settore_stampa,
            priorita: v.priorita_voce,
            quantita_attuale: v.quantita || 0,
            scorta_attiva: !!v.attiva,
            stato_scorta_corrente: statoVisivo,
            consumo_15min: consumo15,
            consumo_1h: consumo1h,
            media_storica_unita_ora: parseFloat(storicoVoce.media_unita_ora.toFixed(2)),
            occorrenze_storiche: storicoVoce.occorrenze,
            modalita: pesi.modalita,
            pesi: { alpha: pesi.alpha, beta: pesi.beta, gamma: pesi.gamma },
            consumo_atteso_unita_min: parseFloat(consumoAttUnitaMin.toFixed(4)),
            tempo_esaurimento_sec: tempoEsaurSec === Infinity ? null : Math.round(tempoEsaurSec),
            tempo_residuo_evento_sec: tRes,
            tempo_riapprovvigionamento_sec: v.tempo_riapprovvigionamento,
            U: parseFloat(U.toFixed(2)),
            stato,
            suggerimento: stato === 'urgente'
                ? { quantita: quantitaSuggerita(consumoAttUnitaMin, v.tempo_riapprovvigionamento) }
                : null,
        })
    }

    return { configurazione: config, generato_a: new Date().toISOString(), predizioni: risultati }
}

async function eseguiPredizionePerVoce(voce_id) {
    const res = await eseguiPredizione({ filtroVociIds: [voce_id] })
    return res.predizioni[0] || null
}

module.exports = {
    eseguiPredizione,
    eseguiPredizionePerVoce,
    // Esposti per i test unitari
    _interno: {
        calcolaPesi,
        consumoAtteso,
        tempoEsaurimentoSec,
        calcolaU,
        classifica,
        quantitaSuggerita,
        tempoResiduoEventoSec,
        aggregaConsumiCondivisi,
        PESI_NORMALE,
        PESI_PICCO,
        PRIORITA_VALORE,
        SOGLIA_PICCO_MULT,
        MIN_OCCORRENZE_STORICHE,
        MOLTIPLICATORE_CONTESTO,
        MOLTIPLICATORE_SUGGERIMENTO,
    },
}

// Printer Dispatcher: orchestra il flusso dalla comanda (generata dallo smistatore)
// al buffer ESC/POS (prodotto dal formatter) fino alla stampante fisica (via TCP raw).
//
// Punto chiave architetturale: il transport TCP è SEMPRE lo stesso, sia che la
// stampante sia un emulatore locale su 127.0.0.1 sia che sia hardware reale
// in produzione. Cambia solo il record nella tabella stampante.

const net = require('net')
const db = require('../db')
const formatter = require('./formatter')
const smistatore = require('./smistatore')

const TIMEOUT_TCP_MS = 5000
let ioRef = null

function setIo(io) { ioRef = io }

function emit(event, payload) {
    if (ioRef) ioRef.emit(event, payload)
}

// Invia un buffer alla stampante via TCP raw socket.
// Risolve con { ok:true, durata_ms } o { ok:false, errore, codice }.
function inviaBuffer(stampante, buffer) {
    return new Promise((resolve) => {
        const inizio = Date.now()
        let risolto = false
        const fine = (esito) => {
            if (risolto) return
            risolto = true
            esito.durata_ms = Date.now() - inizio
            resolve(esito)
        }

        const socket = new net.Socket()
        socket.setTimeout(TIMEOUT_TCP_MS)

        socket.once('error', (err) => {
            fine({ ok: false, errore: err.message, codice: err.code || 'ERR' })
            try { socket.destroy() } catch {}
        })
        socket.once('timeout', () => {
            fine({ ok: false, errore: 'timeout', codice: 'ETIMEDOUT' })
            try { socket.destroy() } catch {}
        })
        socket.once('close', () => {
            // Se chiude prima che abbiamo concluso scrittura → errore
            fine({ ok: true })
        })

        socket.connect(stampante.porta, stampante.indirizzo_ip, () => {
            socket.write(buffer, (err) => {
                if (err) {
                    fine({ ok: false, errore: err.message, codice: err.code || 'EWRITE' })
                    try { socket.destroy() } catch {}
                    return
                }
                // Diamo un breve attimo alla stampante per assorbire, poi chiudiamo
                socket.end()
            })
        })
    })
}

async function risolviStampantePrimaria(reparto) {
    const [righe] = await db.query(
        `SELECT * FROM stampante
         WHERE reparto = ? AND primaria = 1 AND attiva = 1
         ORDER BY id ASC LIMIT 1`,
        [reparto]
    )
    return righe[0] || null
}

async function logStampa({ ordine_id, stampante_id, reparto, payload, esito, errore, durata_ms }) {
    try {
        await db.query(
            `INSERT INTO stampa_eseguita (ordine_id, stampante_id, reparto, payload, esito, errore, durata_ms)
             VALUES (?, ?, ?, ?, ?, ?, ?)`,
            [ordine_id, stampante_id || null, reparto, JSON.stringify(payload || null), esito, errore || null, durata_ms || null]
        )
    } catch (err) {
        console.error('logStampa errore:', err.message)
    }
}

// Funzione principale: invia una comanda alla stampante del reparto.
// Fire-and-forget: non lancia mai eccezioni verso il chiamante.
async function inviaComanda(comanda, opzioni = {}) {
    const reparto = comanda.reparto
    const ordine_id = comanda.ordine_id

    // Risolvi stampante primaria del reparto
    const stampante = await risolviStampantePrimaria(reparto)
    if (!stampante) {
        await logStampa({ ordine_id, reparto, payload: comanda, esito: 'no_stampante', errore: `Nessuna stampante primaria attiva per il reparto ${reparto}` })
        emit('stampa_fallita', { ordine_id, reparto, motivo: 'no_stampante' })
        return { ok: false, motivo: 'no_stampante' }
    }

    // Modalità di stampa: ricavata dalla prima riga della comanda (tutte le righe
    // dello stesso reparto hanno la stessa modalita), default singola_multipla.
    const modalita = opzioni.modalita_stampa || comanda.modalita_stampa || 'singola_multipla'

    let pagine
    try {
        pagine = await formatter.pagineDaInviare(comanda, modalita, { modello: stampante.modello })
    } catch (err) {
        await logStampa({ ordine_id, stampante_id: stampante.id, reparto, payload: comanda, esito: 'errore', errore: `Formattazione fallita: ${err.message}` })
        emit('stampa_fallita', { ordine_id, reparto, motivo: 'formattazione', errore: err.message })
        return { ok: false, motivo: 'formattazione' }
    }

    // Invia in sequenza (i modelli economici non amano connessioni concorrenti)
    let durataTotale = 0
    for (const buffer of pagine) {
        const ris = await inviaBuffer(stampante, buffer)
        durataTotale += ris.durata_ms || 0

        if (!ris.ok) {
            // Marca stampante offline
            try {
                await db.query("UPDATE stampante SET stato='offline' WHERE id=?", [stampante.id])
            } catch {}
            smistatore.setStatoStampante(reparto, 'offline')
            emit('stampante_offline', { reparto, stampante_id: stampante.id, errore: ris.errore })

            await logStampa({ ordine_id, stampante_id: stampante.id, reparto, payload: comanda, esito: 'errore', errore: `${ris.codice}: ${ris.errore}`, durata_ms: durataTotale })
            emit('stampa_fallita', { ordine_id, reparto, motivo: 'tcp', codice: ris.codice, errore: ris.errore })
            return { ok: false, motivo: 'tcp', codice: ris.codice }
        }
    }

    // Successo: assicurati che lo stato sia online (potrebbe essere stato spento prima)
    try {
        await db.query("UPDATE stampante SET stato='online' WHERE id=? AND stato!='online'", [stampante.id])
    } catch {}
    smistatore.setStatoStampante(reparto, 'online')

    await logStampa({ ordine_id, stampante_id: stampante.id, reparto, payload: comanda, esito: 'ok', durata_ms: durataTotale })
    emit('comanda_stampata', { ordine_id, reparto, stampante_id: stampante.id, durata_ms: durataTotale, pagine: pagine.length })
    return { ok: true, durata_ms: durataTotale, pagine: pagine.length }
}

// Copia cliente: scontrino riepilogativo su stampante reparto cassa
async function inviaCopiaCliente(dati) {
    const reparto = 'cassa'
    const ordine_id = dati.ordine_id

    const stampante = await risolviStampantePrimaria(reparto)
    if (!stampante) {
        await logStampa({ ordine_id, reparto, payload: dati, esito: 'no_stampante', errore: `Nessuna stampante primaria attiva per il reparto ${reparto}` })
        emit('stampa_fallita', { ordine_id, reparto, motivo: 'no_stampante' })
        return { ok: false, motivo: 'no_stampante' }
    }

    let buffer
    try {
        buffer = await formatter.formattaCopiaCliente(dati, { modello: stampante.modello })
    } catch (err) {
        await logStampa({ ordine_id, stampante_id: stampante.id, reparto, payload: dati, esito: 'errore', errore: `Formattazione fallita: ${err.message}` })
        emit('stampa_fallita', { ordine_id, reparto, motivo: 'formattazione', errore: err.message })
        return { ok: false, motivo: 'formattazione' }
    }

    const ris = await inviaBuffer(stampante, buffer)
    if (!ris.ok) {
        try {
            await db.query("UPDATE stampante SET stato='offline' WHERE id=?", [stampante.id])
        } catch {}
        smistatore.setStatoStampante(reparto, 'offline')
        emit('stampante_offline', { reparto, stampante_id: stampante.id, errore: ris.errore })
        await logStampa({ ordine_id, stampante_id: stampante.id, reparto, payload: dati, esito: 'errore', errore: `${ris.codice}: ${ris.errore}`, durata_ms: ris.durata_ms })
        emit('stampa_fallita', { ordine_id, reparto, motivo: 'tcp', codice: ris.codice, errore: ris.errore })
        return { ok: false, motivo: 'tcp', codice: ris.codice }
    }

    try {
        await db.query("UPDATE stampante SET stato='online' WHERE id=? AND stato!='online'", [stampante.id])
    } catch {}
    smistatore.setStatoStampante(reparto, 'online')

    await logStampa({ ordine_id, stampante_id: stampante.id, reparto, payload: dati, esito: 'ok', durata_ms: ris.durata_ms })
    emit('comanda_stampata', { ordine_id, reparto, stampante_id: stampante.id, durata_ms: ris.durata_ms, pagine: 1, tipo: 'copia_cliente' })
    return { ok: true, durata_ms: ris.durata_ms, pagine: 1 }
}

// Pagina di test per una stampante specifica (utile dall'UI admin)
async function stampaTestPage(stampante_id) {
    const [righe] = await db.query('SELECT * FROM stampante WHERE id = ?', [stampante_id])
    const stampante = righe[0]
    if (!stampante) return { ok: false, motivo: 'stampante_inesistente' }

    const pagine = await formatter.pagineDiTest(stampante)
    for (const buf of pagine) {
        const ris = await inviaBuffer(stampante, buf)
        if (!ris.ok) {
            await logStampa({ ordine_id: 0, stampante_id, reparto: stampante.reparto, payload: { test: true }, esito: 'errore', errore: ris.errore, durata_ms: ris.durata_ms })
            return { ok: false, motivo: 'tcp', codice: ris.codice, errore: ris.errore }
        }
    }
    await logStampa({ ordine_id: 0, stampante_id, reparto: stampante.reparto, payload: { test: true }, esito: 'ok' })
    return { ok: true }
}

module.exports = {
    setIo,
    inviaComanda,
    inviaCopiaCliente,
    stampaTestPage,
}

// Smistatore Intelligente Multi-Reparto
// Routing dinamico delle righe ordine ai reparti di stampa con bilanciamento del carico.
// Stato code mantenuto in memoria: alla conferma ordine si calcola carico, si assegna il
// reparto a carico minore, si batcha per voce, si ranka per priorità P e si emettono comande.

const PESI = { A: 1.0, B: 50.0, C: 10.0, D: 0.01, E: 30.0 }
const ALPHA_STRESS = 1.3
const BETA_OFFLINE = 2.0
const SOGLIA_STRESS_TASK = 5
const FINESTRA_BATCH_MS = 30_000
const TEMPO_PREP_DEFAULT = 60

// reparto -> array di task in coda
const code = new Map()
// reparto -> 'online' | 'offline'
const statoStampanti = new Map()
// reparto -> array di reparti fallback (es. { cucina: ['griglia'] })
const fallbackReparti = new Map()

function getCoda(reparto) {
    if (!code.has(reparto)) code.set(reparto, [])
    return code.get(reparto)
}

function stampanteOnline(reparto) {
    return statoStampanti.get(reparto) !== 'offline'
}

// carico_reparto = n_task * t_prep_residuo * α_stress * β_stampante
function caricoReparto(reparto) {
    const tasks = getCoda(reparto)
    const n = tasks.length
    if (n === 0) return 0
    const tPrep = tasks.reduce((acc, t) => acc + (t.tempo_preparazione_residuo || 0), 0)
    const alpha = n >= SOGLIA_STRESS_TASK ? ALPHA_STRESS : 1.0
    const beta = stampanteOnline(reparto) ? 1.0 : BETA_OFFLINE
    return n * tPrep * alpha * beta
}

// arg min su reparti compatibili; tie-break: timestamp ultimo task più vecchio
function selectMinCarico(repartiCompatibili) {
    let scelto = null, caricoMin = Infinity, lastTsMin = Infinity
    for (const r of repartiCompatibili) {
        const c = caricoReparto(r)
        const coda = getCoda(r)
        const lastTs = coda.length ? coda[coda.length - 1].timestamp : 0
        if (c < caricoMin || (c === caricoMin && lastTs < lastTsMin)) {
            caricoMin = c
            lastTsMin = lastTs
            scelto = r
        }
    }
    return scelto
}

// P = A·t_attesa + B·π_a + C·s − D·carico(r) − E·rischio_scorte
function calcolaRanking(task, reparto, ora = Date.now()) {
    const tAttesa = (ora - task.timestamp) / 1000
    const piAsporto = task.priorita === 'asporto' ? 1.0 : 0.0
    const s = 1.0 / ((task.tempo_preparazione || TEMPO_PREP_DEFAULT) + 1)
    const carico = caricoReparto(reparto)
    const rischio = task.rischio_scorte || 0
    return PESI.A * tAttesa + PESI.B * piAsporto + PESI.C * s - PESI.D * carico - PESI.E * rischio
}

function repartiCompatibili(task) {
    const primario = task.settore_stampa || 'default'
    const fallback = fallbackReparti.get(primario) || []
    const candidati = [primario, ...fallback]
    // Se il primario è offline e ha fallback, escludi primario; altrimenti si forza il routing
    const online = candidati.filter(stampanteOnline)
    if (online.length > 0) return online
    return [primario]
}

function rigaToTasks(riga, ordineId, asporto, ora) {
    const scortaInsufficiente = riga.scorta_attiva && riga.scorta_quantita != null && riga.scorta_quantita < riga.quantita
    if (scortaInsufficiente) {
        return { bloccato: { ordine_id: ordineId, voce_id: riga.voce_id, nome: riga.nome, motivo: 'scorta insufficiente', richiesta: riga.quantita, disponibile: riga.scorta_quantita } }
    }
    const tPrep = riga.tempo_preparazione || TEMPO_PREP_DEFAULT
    // singola_singola → 1 task per porzione, altrimenti 1 task con quantità cumulata
    const esplodi = riga.modalita_stampa === 'singola_singola'
    const nTask = esplodi ? riga.quantita : 1
    const qta = esplodi ? 1 : riga.quantita
    const rischio = riga.scorta_attiva && riga.scorta_quantita != null && riga.scorta_quantita <= (riga.soglia_rosso || 3) ? 1.0 : 0.0
    const tasks = []
    for (let i = 0; i < nTask; i++) {
        tasks.push({
            ordine_id: ordineId,
            voce_id: riga.voce_id,
            nome: riga.nome,
            prezzo: parseFloat(riga.prezzo || 0),
            quantita: qta,
            tempo_preparazione: tPrep,
            tempo_preparazione_residuo: tPrep,
            timestamp: ora,
            settore_stampa: riga.settore_stampa,
            priorita: asporto ? 'asporto' : 'tavolo',
            note: riga.note || [],
            rischio_scorte: rischio,
        })
    }
    return { tasks }
}

function batchPerReparto(taskAssegnati, ora) {
    const perReparto = new Map()
    for (const t of taskAssegnati) {
        if (!perReparto.has(t.reparto_assegnato)) perReparto.set(t.reparto_assegnato, [])
        perReparto.get(t.reparto_assegnato).push(t)
    }
    const risultato = new Map()
    for (const [reparto, lista] of perReparto) {
        const aggregati = new Map()
        for (const t of lista) {
            const chiave = t.voce_id
            const esistente = aggregati.get(chiave)
            if (esistente && (ora - esistente.timestamp) <= FINESTRA_BATCH_MS) {
                esistente.quantita += t.quantita
                esistente.note = [...esistente.note, ...t.note]
                esistente.P = Math.max(esistente.P, t.P)
            } else {
                aggregati.set(chiave, { ...t, note: [...t.note] })
            }
        }
        risultato.set(reparto, [...aggregati.values()].sort((a, b) => b.P - a.P))
    }
    return risultato
}

// Routing principale di un ordine: ritorna { comande, bloccati }
function routeOrder({ ordine_id, righe, asporto = false }) {
    const ora = Date.now()
    const tasks = []
    const bloccati = []

    for (const riga of righe) {
        const { tasks: ts, bloccato } = rigaToTasks(riga, ordine_id, asporto, ora)
        if (bloccato) { bloccati.push(bloccato); continue }
        tasks.push(...ts)
    }

    // Assegnazione greedy: ogni task aggiorna lo stato della coda per i task successivi
    const assegnati = []
    for (const t of tasks) {
        const reparti = repartiCompatibili(t)
        const repartoScelto = selectMinCarico(reparti) || reparti[0]
        getCoda(repartoScelto).push(t)
        const conReparto = { ...t, reparto_assegnato: repartoScelto }
        conReparto.P = calcolaRanking(conReparto, repartoScelto, ora)
        assegnati.push(conReparto)
    }

    const perReparto = batchPerReparto(assegnati, ora)

    const comande = []
    for (const [reparto, righeBatch] of perReparto) {
        comande.push({
            ordine_id,
            reparto,
            asporto,
            timestamp: ora,
            stampante_online: stampanteOnline(reparto),
            righe: righeBatch.map(r => ({
                voce_id: r.voce_id,
                nome: r.nome,
                quantita: r.quantita,
                note: r.note,
                P: parseFloat(r.P.toFixed(3)),
            })),
        })
    }
    // Ordinamento globale per priorità: comanda con riga di P massimo per prima
    comande.sort((a, b) => {
        const pa = a.righe.length ? a.righe[0].P : -Infinity
        const pb = b.righe.length ? b.righe[0].P : -Infinity
        return pb - pa
    })

    return { comande, bloccati }
}

// Libera un task dalla coda (da chiamare quando il reparto lo ha completato)
function completaTask(reparto, voce_id, ordine_id) {
    const coda = getCoda(reparto)
    const idx = coda.findIndex(t => t.voce_id === voce_id && (!ordine_id || t.ordine_id === ordine_id))
    if (idx >= 0) coda.splice(idx, 1)
    return idx >= 0
}

function setStatoStampante(reparto, stato) {
    statoStampanti.set(reparto, stato === 'offline' ? 'offline' : 'online')
}

function setFallback(reparto, repartiAlternativi) {
    fallbackReparti.set(reparto, Array.isArray(repartiAlternativi) ? repartiAlternativi : [])
}

function snapshot() {
    const code_snapshot = {}
    for (const [reparto, tasks] of code) {
        code_snapshot[reparto] = {
            numero_task: tasks.length,
            carico: parseFloat(caricoReparto(reparto).toFixed(2)),
            stampante: stampanteOnline(reparto) ? 'online' : 'offline',
            task: tasks.map(t => ({
                ordine_id: t.ordine_id,
                voce_id: t.voce_id,
                nome: t.nome,
                quantita: t.quantita,
                timestamp: t.timestamp,
            })),
        }
    }
    return code_snapshot
}

function reset() {
    code.clear()
}

module.exports = {
    routeOrder,
    completaTask,
    setStatoStampante,
    setFallback,
    snapshot,
    reset,
    // Esposti per test/debug
    _carichi: { caricoReparto, selectMinCarico, calcolaRanking },
}

